:root {
  --card-bg: #fdf6e3;
  --card-border: #c8a96e;
  --stamp-bg: #e8f4e8;
  --stamp-border: #4a7c4a;
  --stamp-text: #2d5a2d;
  --stamp-icon-color: #4a7c4a;
  --sky-bg: #bde0f7;
  --sun-color: #f5c842;
  --cloud-color: #ffffff;
  --ground-bg: #7dba6f;
  --mountain-color: #5a8a4a;
  --mountain-dark: #3d6b35;
  --dest-label-color: #9b6e3a;
  --dest-name-color: #5a3a1a;
  --divider-color: #c8a96e;
  --dot-color: #c8a96e;
  --to-label-color: #9b6e3a;
  --addr-line-color: #c8a96e;
  --msg-label-color: #9b6e3a;
  --msg-line-color: #d4b896;
  --postmark-color: #c0392b;
  --postmark-text: #ffffff;
  --shadow-color: rgba(139, 90, 43, 0.15);
}

.postcard {
  display: flex;
  flex-direction: row;
  width: 520px;
  height: 300px;
  background: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 6px;
  overflow: hidden;
  margin: 20px auto;
  box-sizing: border-box;
}

.postcard-left {
  display: flex;
  flex-direction: column;
  width: 260px;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}

.stamp-area {
  display: flex;
  justify-content: flex-end;
  padding: 10px 10px 4px 10px;
  background: var(--card-bg);
}

.stamp {
  width: 54px;
  height: 64px;
  background: var(--stamp-bg);
  border: 2px solid var(--stamp-border);
  border-radius: 3px;
  padding: 3px;
  box-sizing: border-box;
}

.stamp-inner {
  width: 100%;
  height: 100%;
  border: 1px dashed var(--stamp-border);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  box-sizing: border-box;
}

.stamp-icon {
  font-size: 20px;
  color: var(--stamp-icon-color);
  line-height: 1;
}

.stamp-value {
  font-size: 7px;
  font-weight: 700;
  color: var(--stamp-text);
  letter-spacing: 0.5px;
  text-align: center;
}

.scene {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.scene-sky {
  flex: 1;
  background: var(--sky-bg);
  position: relative;
  overflow: hidden;
}

.sun {
  position: absolute;
  top: 14px;
  left: 20px;
  width: 28px;
  height: 28px;
  background: var(--sun-color);
  border-radius: 50%;
}

.cloud {
  position: absolute;
  background: var(--cloud-color);
  border-radius: 20px;
  height: 16px;
}

.cloud-1 {
  width: 60px;
  top: 18px;
  left: 80px;
}

.cloud-2 {
  width: 44px;
  top: 10px;
  left: 170px;
  height: 12px;
}

.scene-ground {
  height: 60px;
  background: var(--ground-bg);
  position: relative;
  overflow: hidden;
}

.mountain {
  position: absolute;
  bottom: 0;
  width: 0;
  height: 0;
  border-style: solid;
}

.mountain-1 {
  border-width: 0 50px 55px 50px;
  border-color: transparent transparent var(--mountain-color) transparent;
  left: 40px;
}

.mountain-2 {
  border-width: 0 38px 44px 38px;
  border-color: transparent transparent var(--mountain-dark) transparent;
  left: 130px;
}

.destination {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 10px;
  background: var(--card-bg);
  gap: 2px;
}

.dest-label {
  font-size: 9px;
  font-weight: 600;
  color: var(--dest-label-color);
  letter-spacing: 2px;
  text-transform: uppercase;
}

.dest-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--dest-name-color);
  letter-spacing: 1px;
}

.postcard-divider {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 20px;
  flex-shrink: 0;
  gap: 4px;
  padding: 12px 0;
}

.divider-line {
  width: 1px;
  flex: 1;
  background: var(--divider-color);
}

.divider-dots {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.divider-dots span {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--dot-color);
  display: block;
}

.postcard-right {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 12px 14px 12px 6px;
  gap: 16px;
  box-sizing: border-box;
}

.address-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.to-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--to-label-color);
  letter-spacing: 1px;
}

.address-lines {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.address-line {
  height: 2px;
  background: var(--addr-line-color);
  border-radius: 1px;
}

.address-line.long { width: 100%; }
.address-line.medium { width: 75%; }
.address-line.short { width: 50%; }

.message-section {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
  position: relative;
}

.message-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--msg-label-color);
  letter-spacing: 2px;
  text-transform: uppercase;
}

.message-lines {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.msg-line {
  height: 1px;
  background: var(--msg-line-color);
  width: 100%;
}

.msg-line.short {
  width: 60%;
}

.postmark {
  position: absolute;
  bottom: 4px;
  right: 0;
}

.postmark-circle {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  border: 3px solid var(--postmark-color);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  background: transparent;
}

.postmark-date {
  font-size: 10px;
  font-weight: 700;
  color: var(--postmark-color);
  letter-spacing: 0.5px;
}

.postmark-year {
  font-size: 11px;
  font-weight: 700;
  color: var(--postmark-color);
}
